import React, { useEffect, useState } from 'react';
import Papa from 'papaparse';
import axios from 'axios';

const CsvLoader = ({ onLoadData }) => {
  const [vehicles, setVehicles] = useState([]);
  const [stations, setStations] = useState([]);
  const [steps, setSteps] = useState([]);

  useEffect(() => {
    loadCsvData('./vehicles.csv', setVehicles);
    loadCsvData('./stations.csv', setStations);
    loadCsvData('./steps.csv', setSteps);
  }, []);

  const loadCsvData = (url, setData) => {
    axios.get(url).then((response) => {
      Papa.parse(response.data, {
        header: true,
        dynamicTyping: true,
        complete: (results) => {
          setData(results.data);
        },
      });
    });
  };

  useEffect(() => {
    if (vehicles.length && stations.length && steps.length) {
      onLoadData({ vehicles, stations, steps });
    }
  }, [vehicles, stations, steps, onLoadData]);

  return null;
};

export default CsvLoader;
